    const rspressCoreThemePath = node_path.dirname(rspressCoreThemeEntry);
    const aliases = {};
    const existingThemeAliasList = Array.isArray(existingThemeAlias) ? existingThemeAlias : 'string' == typeof existingThemeAlias ? [
        existingThemeAlias
    ] : [];
    const themeAliasCandidates = existingThemeAliasList.filter((value)=>'string' == typeof value).filter((value)=>value !== ckThemeExportsPath);
    if (!themeAliasCandidates.includes(rspressCoreThemePath)) themeAliasCandidates.push(rspressCoreThemePath);
    const rspressThemeIndex = themeAliasCandidates.indexOf(rspressCoreThemePath);
